"""Bounded diagnostic tile and hand-drawn 1-bit serif inscription atlas."""
from PIL import Image
from pathlib import Path
P=Path(__file__).resolve().parent
# 5x7 skeletons. Serifs are added in the 8x12 cells; no system font dependency.
rows={'A':['01110','10001','10001','11111','10001','10001','10001'],'B':['11110','10001','10001','11110','10001','10001','11110'],'C':['01111','10000','10000','10000','10000','10000','01111'],'D':['11110','10001','10001','10001','10001','10001','11110'],'E':['11111','10000','10000','11110','10000','10000','11111'],'F':['11111','10000','10000','11110','10000','10000','10000'],'G':['01111','10000','10000','10111','10001','10001','01111'],'H':['10001','10001','10001','11111','10001','10001','10001'],'I':['11111','00100','00100','00100','00100','00100','11111'],'J':['00111','00010','00010','00010','10010','10010','01100'],'K':['10001','10010','10100','11000','10100','10010','10001'],'L':['10000','10000','10000','10000','10000','10000','11111'],'M':['10001','11011','10101','10101','10001','10001','10001'],'N':['10001','11001','11001','10101','10011','10011','10001'],'O':['01110','10001','10001','10001','10001','10001','01110'],'P':['11110','10001','10001','11110','10000','10000','10000'],'Q':['01110','10001','10001','10001','10101','10010','01101'],'R':['11110','10001','10001','11110','10100','10010','10001'],'S':['01111','10000','10000','01110','00001','00001','11110'],'T':['11111','00100','00100','00100','00100','00100','00100'],'U':['10001','10001','10001','10001','10001','10001','01110'],'V':['10001','10001','10001','10001','10001','01010','00100'],'W':['10001','10001','10001','10101','10101','11011','10001'],'X':['10001','10001','01010','00100','01010','10001','10001'],'Y':['10001','10001','01010','00100','00100','00100','00100'],'Z':['11111','00001','00010','00100','01000','10000','11111'],'0':['01110','10001','10011','10101','11001','10001','01110'],'1':['00100','01100','00100','00100','00100','00100','01110'],'2':['01110','10001','00001','00010','00100','01000','11111'],'3':['11110','00001','00001','01110','00001','00001','11110'],'4':['00010','00110','01010','10010','11111','00010','00010'],'5':['11111','10000','10000','11110','00001','00001','11110'],'6':['01110','10000','10000','11110','10001','10001','01110'],'7':['11111','00001','00010','00100','01000','01000','01000'],'8':['01110','10001','10001','01110','10001','10001','01110'],'9':['01110','10001','10001','01111','00001','00001','01110'],'.':['00000','00000','00000','00100','00100','00000','00000']}
atlas=Image.new('1',(128,64))
for ch,rs in rows.items():
    n=ord(ch)-32; ox=n%16*8; oy=n//16*12
    for yy in range(10):
        for xx,v in enumerate(rs[yy*7//10]):
            if v=='1': atlas.putpixel((ox+1+xx,oy+yy+1),1)
    # Foot serifs on vertical terminal stems, within cell.
    for xx,v in enumerate(rs[-1]):
        if v=='1':
            for sx in [xx,xx+1,xx+2]: atlas.putpixel((ox+sx,oy+10),1)
atlas.save(P/'source/inscription-atlas.png')
def arr(f,typ,name,data):
    f.write('_Alignas(4) const '+typ+' '+name+'['+str(len(data))+'] = {\n')
    for i in range(0,len(data),24):f.write(','.join(map(str,data[i:i+24]))+',\n')
    f.write('};\n')
with (P/'engine_assets.c').open('w') as f:
    f.write('#include "engine_assets.h"\n')
    arr(f,'uint8_t','inscription_atlas',list(atlas.tobytes()))
    arr(f,'uint8_t','diagnostic_tile',[(x*3+y*2+((x//8^y//8)&1)*64)%256 for y in range(64) for x in range(64)])
(P/'engine_assets.h').write_text('#include <stdint.h>\nextern const uint8_t inscription_atlas[1024], diagnostic_tile[4096];\n')

tile=Image.new('L',(64,64));tile.putdata([(x*3+y*2+((x//8^y//8)&1)*64)%256 for y in range(64) for x in range(64)]);tile.save(P/'source/diagnostic-tile.png')
